fc1a0\", \"elType\": \"column\", \"settings\": {\"_column_size\": 33, \"_inline_size\": null}, \"elements\": [{\"id\": \"4efcfb53\", \"elType\": \"widget\", \"widgetType\": \"testimonial\", \"settings\": {\"testimonial_content\": \"Satu pintu untuk servis, ban, dan oli. Laporan Web Fleet-nya memudahkan audit perawatan.\", \"testimonial_name\": \"Sarah Wijaya\", \"testimonial_job\": \"Fleet Manager, Logistik Sumatera\", \"alignment\": \"center\", \"_animation\": \"fadeInUp\", \"_animation_delay\": 80, \"testimonial_image\": {\"id\": 79, \"url\": \"http://localhost:8080/wp-content/uploads/2026/10/av-sw.png\", \"alt\": \"\", \"size\": \"\"}}, \"elements\": []}], \"isInner\": false}, {\"id\": \"4be98add\", \"elType\": \"column\", \"settings\": {\"_column_size\": 33, \"_inline_size\": null}, \"elements\": [{\"id\": \"c33d6d89\", \"elType\": \"widget\", \"widgetType\": \"testimonial\", \"settings\": {\"testimonial_content\": \"Sparepart selalu original dan ready stock. Sudah 5 tahun armada kami dirawat di sini.\", \"testimonial_name\": \"Agus Pratama\", \"testimonial_job\": \"Direktur CV. Barumun Cargo\", \"alignment\": \"center\", \"_animation\": \"fadeInUp\", \"_animation_delay\": 160, \"testimonial_image\": {\"id\": 80, \"url\": \"http://localhost:8080/wp-content/uploads/2026/10/av-ap.png\", \"alt\": \"\", \"size\": \"\"}}, \"elements\": []}], \"isInner\": false}], \"isInner\": false}, {\"id\": \"78c50705\", \"elType\": \"section\", \"settings\": {\"content_width\": {\"unit\": \"px\", \"size\": 1220}, \"padding\": {\"unit\": \"px\", \"top\": 70, \"right\": 0, \"bottom\": 10, \"left\": 0, \"isLinked\": false}, \"padding_tablet\": {\"unit\": \"px\", \"top\": 46, \"right\": 0, \"bottom\": 16, \"left\": 0, \"isLinked\": false}, \"padding_mobile\": {\"unit\": \"px\", \"top\": 32, \"right\": 0, \"bottom\": 16, \"left\": 0, \"isLinked\": false}}, \"elements\": [{\"id\": \"376dc04b\", \"elType\": \"column\", \"settings\": {\"_column_size\": 100, \"_inline_size\": null}, \"elements\": [{\"id\": \"5e92f3e1\", \"elType\": \"widget\", \"widgetType\": \"text-editor\", \"settings\": {\"editor\": \"<p><span class=\\\"mt-eyebrow\\\">TANYA JAWAB</span></p>\", \"align\": \"center\", \"_animation\": \"fadeInUp\", \"_animation_delay\": 0}, \"elements\": []}, {\"id\": \"f5680f48\", \"elType\": \"widget\", \"widgetType\": \"heading\", \"settings\": {\"title\": \"Sering Ditanyakan Mitra\", \"align\": \"center\", \"title_color\": \"var(--e-global-color-primary)\", \"typography_typography\": \"custom\", \"typography_font_family\": \"Barlow\", \"typography_font_weight\": \"700\", \"typography_font_size\": {\"unit\": \"px\", \"size\": 36}, \"_animation\": \"fadeInUp\", \"_animation_delay\": 80, \"typography_font_size_tablet\": {\"unit\": \"px\", \"size\": 30}, \"typography_font_size_mobile\": {\"unit\": \"px\", \"size\": 26}}, \"elements\": []}], \"isInner\": false}], \"isInner\": false}, {\"id\": \"e889fbc9\", \"elType\": \"section\", \"settings\": {\"content_width\": {\"unit\": \"px\", \"size\": 1220}, \"padding\": {\"unit\": \"px\", \"top\": 10, \"right\": 0, \"bottom\": 70, \"left\": 0, \"isLinked\": false}, \"padding_tablet\": {\"unit\": \"px\", \"top\": 16, \"right\": 0, \"bottom\": 46, \"left\": 0, \"isLinked\": false}, \"padding_mobile\": {\"unit\": \"px\", \"top\": 16, \"right\": 0, \"bottom\": 32, \"left\": 0, \"isLinked\": false}}, \"elements\": [{\"id\": \"f557f597\", \"elType\": \"column\", \"settings\": {\"_column_size\": 100, \"_inline_size\": null}, \"elements\": [{\"id\": \"cda52125\", \"elType\": \"widget\", \"widgetType\": \"accordion\", \"settings\": {\"tabs\": [{\"tab_title\": \"Bagaimana cara booking servis armada?\", \"tab_content\": \"<p>Seluruh booking dilakukan via portal <strong>Web Fleet</strong>. Masuk di halaman <strong>Login Web Fleet</strong>, atau klik <strong>Daftar Mitra Baru</strong> bila perusahaan Anda belum terdaftar. Untuk respon kilat, hubungi WhatsApp 0812-3456-7890.</p>\"}, {\"tab_title\": \"Apakah menerima kontrak perawatan armada perusahaan (fleet)?\", \"tab_content\": \"<p>Ya \\u2014 fleet adalah fokus utama kami. Tersedia paket servis berkala, prioritas antrean bengkel, dan laporan perawatan per unit via Web Fleet. Hubungi tim kami untuk penawaran kontrak.</p>\"}, {\"tab_title\": \"Apakah sparepart yang dijual original?\", \"tab_content\": \"<p>100% original. Kami distributor nasional resmi Pertamina, Mobil Delvac, Dunlop, Incoe/GS Astra, dan sparepart OEM \\u2014 lengkap dengan garansi prinsipal.</p>\"}, {\"tab_title\": \"Berapa lama overhaul mesin diesel?\", \"tab_content\": \"<p>Tergantung tingkat kerusakan; estimasi pasti diberikan setelah inspeksi unit. Progress pengerjaan dapat dipantau melalui riwayat servis di Web Fleet.</p>\"}, {\"tab_title\": \"Wilayah mana saja yang dilayani?\", \"tab_content\": \"<p>Bengkel pusat di KIM III Medan melayani seluruh Kota Medan dan Sumatera Utara, plus service car untuk panggilan darurat. Pengiriman sparepart menjangkau seluruh Sumatera.</p>\"}, {\"tab_title\": \"Bagaimana cara menjadi mitra Web Fleet?\", \"tab_content\": \"<p>Klik <strong>Daftar Mitra Baru</strong>, isi data perusahaan dan kontak PIC. Tim kami verifikasi maksimal 1x24 jam kerja, setelah itu akun langsung bisa dipakai booking.</p>\"}], \"title_html_tag\": \"h4\", \"_animation\": \"fadeInUp\", \"_animation_delay\": 0}, \"elements\": []}], \"isInner\": false}], \"isInner\": false}, {\"id\": \"4fda821f\", \"elType\": \"section\", \"settings\": {\"layout\": \"full_width\", \"background_background\": \"classic\", \"background_color\": \"var(--e-global-color-dark)\", \"padding\": {\"unit\": \"px\", \"top\": 44, \"right\": 0, \"bottom\": 48, \"left\": 0, \"isLinked\": false}, \"css_classes\": \"mt-brands\", \"padding_tablet\": {\"unit\": \"px\", \"top\": 29, \"right\": 0, \"bottom\": 31, \"left\": 0, \"isLinked\": false}, \"padding_mobile\": {\"unit\": \"px\", \"top\": 20, \"right\": 0, \"bottom\": 22, \"left\": 0, \"isLinked\": false}}, \"elements\": [{\"id\": \"b01a8a