t-navy) !important;}\n::selection{background:var(--mt-red);color:#fff;}\n.elementor-widget-testimonial .elementor-testimonial__image img{border:2px solid var(--mt-gold);}\n.mt-flinks a:hover,.mt-copy a:hover{color:var(--mt-gold) !important;}\n/* MT BRAND CARDS */\n.mt-brand{text-align:center;padding:22px 10px;border:1px solid rgba(245,158,11,.28);border-radius:14px;background:rgba(255,255,255,.03);transition:transform .25s ease,box-shadow .25s ease,border-color .25s ease;height:100%;}\n.mt-brand:hover{transform:translateY(-5px);border-color:var(--mt-gold);box-shadow:0 14px 30px rgba(0,0,0,.35),0 0 0 1px var(--mt-gold);}\n.mt-brand-badge{display:inline-flex;width:68px;height:68px;border-radius:50%;border:2px solid var(--mt-gold);color:var(--mt-cream);font-family:Barlow,sans-serif;font-weight:800;font-size:24px;align-items:center;justify-content:center;margin-bottom:12px;background:rgba(245,158,11,.08);}\n.mt-brand strong{display:block;color:#fff;font-family:Barlow,sans-serif;font-weight:800;font-size:17px;letter-spacing:1px;margin-bottom:4px;}\n.mt-brand small{display:block;color:var(--mt-slate);font-size:12px;}\n.mt-brands-strip .elementor-top-column + .elementor-top-column{border:none !important;}\n/* MT BRAND ONE + KONTAK GAP */\n.mt-brands{border-top:4px solid var(--mt-red);}\n.mt-brand-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px;max-width:1220px;margin:22px auto 0;padding:0 20px;}\n@media(max-width:921px){.mt-brand-grid{grid-template-columns:repeat(3,1fr);}}\n@media(max-width:600px){.mt-brand-grid{grid-template-columns:repeat(2,1fr);gap:14px;}}\n.mt-kontak .elementor-top-column{margin-bottom:0;}\n@media(max-width:767px){.mt-kontak .elementor-top-column{margin-left:0 !important;margin-right:0 !important;margin-bottom:20px !important;}.mt-kontak .elementor-top-column:last-child{margin-bottom:0 !important;}}\n/* MT REVAMP: tombol sebaris */\n.mt-btn-row .elementor-widget-wrap > .elementor-element.elementor-widget-button{width:auto;}\n.mt-btn-row 