/* --- tombol pill + micro-interaction --- */\n.elementor-button{border-radius:var(--mt-r-pill)!important;padding-left:26px!important;padding-right:26px!important;}\n.main-header-menu .fleet-btn > .menu-link{border-radius:var(--mt-r-pill)!important;}\n.mt-tb-reg{border-radius:var(--mt-r-pill)!important;}\n.mt-btn{border-radius:var(--mt-r-pill);}\n\n/* --- radius &amp; shadow seragam --- */\n.mt-card,.mt-brand{border-radius:var(--mt-r-md);}\n.mt-card{box-shadow:var(--mt-sh-1);}\n.mt-card:hover{box-shadow:var(--mt-sh-2);}\n.mt-links a{border-radius:var(--mt-r-sm);}\n.elementor-accordion-item{border-radius:var(--mt-r-sm)!important;box-shadow:var(--mt-sh-1);}\n.mt-chips span{border-radius:var(--mt-r-pill)!important;}\n\n/* --- highlight frasa ala headline modern --- */\n\n/* --- kartu statistik melayang di bawah hero --- */\n.mt-stats{background:#fff!important;border:1px solid var(--mt-line);border-radius:var(--mt-r-md)!important;box-shadow:var(--mt-sh-3);max-width:1180px;margin:-72px auto 0!important;padding:30px 12px!important;position:relative;z-index:6;}\n.mt-stats > .elementor-container{max-width:100%!important;}\n.mt-stats .elementor-counter-number{color:var(--mt-navy)!important;font-weight:800;letter-spacing:-.5px;}\n.mt-stats .elementor-counter-number-prefix,.mt-stats .elementor-counter-number-suffix{color:var(--mt-red)!important;font-weight:800;}\n.mt-stats .elementor-counter-title{color:var(--mt-muted)!important;font-weight:600;letter-spacing:.3px;}\n@media(min-width:768px){.mt-stats .elementor-top-column + .elementor-top-column{border-left:1px solid var(--mt-line)!important;}}\n@media(max-width:767px){\n  .mt-stats{margin:0 16px!important;padding:22px 4px!important;}\n  .mt-stats .elementor-row{display:grid;grid-template-columns:repeat(2,1fr);}\n  .mt-stats .elementor-top-column{width:100%!important;padding:12px 8px!important;}\n  .mt-stats .elementor-top-column:nth-child(2n){border-left:1px solid var(--mt-line)!important;}\n  .mt-stats .elementor-top-column:nth-child(-n+2){border-bottom:1px solid var(--mt-line);}\n  .mt-stats .elementor-counter-number{font-size:34px!important;}\n}\n\n/* --- hero: jaga keterbacaan teks di atas foto --- */\n\n/* --- polish mobile --- */\n@media(max-width:600px){\n  .mt-topbar{font-size:11.5px;}\n  .mt-topbar-inner{padding:6px 14px;gap:8px;}\n  .mt-topbar-left{gap:12px;}\n  .mt-topbar-right a{font-size:11.5px;}\n  .mt-tb-reg{padding:3px 10px;}\n  .elementor-button{min-height:46px;}\n}\n@media(max-width:480px){\n  .mt-topbar-right a{font-weight:600;}\n  .mt-topbar-left{gap:10px;}\n}','astra','','inherit','closed','closed','','14-revision-v1','','','2026-10-03 14:27:18','2026-10-03 14:27:18','',14,'http://localhost:8080/?p=106',0,'revision','',0),
(107,0,'2026-10-05 08:01:05','2026-10-05 08:01:05','/* ===== MT PALET GLOBAL (diubah via Elementor > Site Settings > Global Colors) ===== */\r\n:root{\r\n  --mt-navy:var(--e-global-color-primary,#0B2154);\r\n  --mt-red:var(--e-global-color-secondary,#D81324);\r\n  --mt-text:var(--e-global-color-text,#475569);\r\n  --mt-gold:var(--e-global-color-accent,#F59E0B);\r\n  --mt-dark:var(--e-global-color-dark,#001E3D);\r\n  --mt-footer:var(--e-global-color-footer,#000B1D);\r\n  --mt-cream:var(--e-global-color-cream,#FDE68A);\r\n  --mt-bg:var(--e-global-color-bg,#F8FAFC);\r\n  --mt-slate:var(--e-global-color-slate,#CBD5E1);\r\n  --mt-green:var(--e-global-color-green,#22C55E);\r\n  --mt-muted:#64748B;\r\n  --mt-line:#E2E8F0;\r\n  --mt-r-xs:6px;--mt-r-sm:10px;--mt-r-md:16px;--mt-r-pill:999px;\r\n  --mt-sh-1:0 4px 14px rgba(11,33,84,.06);\r\n  --mt-sh-2:0 12px 28px rgba(11,33,84,.10);\r\n  --mt-sh-3:0 22px 48px rgba(11,33,84,.16);\r\n}\r\nASTRA MASTER TRUCK header fixes */\r\n.site-logo-img .custom-logo{max-height:64px !important;width:auto !important;}\r\n.ast-site-title-wrap{display:none !important;}\r\n.main-header-menu .fleet-btn > .menu-link{background:var(--mt-red) !important;color:#fff !important;border-radius:6px !important;padding:8px 18px !important;margin:14px 0 14px 8px !important;line-height:1.4 !important;}\r\n.main-header-menu .fleet-btn > .menu-link:hover{background:var(--mt-navy) !important;color:#fff !important;}\r\n@media(max-width:767px){.mt-gallery{grid-template-columns:repeat(2,1fr) !important;}}\r\n/* MT NAVY PREMIUM HEADER */\r\n.mt-topbar{background:var(--mt-dark);color:var(--mt-slate);font-size:12.5px;}\r\n.mt-topbar-inner{max-width:1220px;margin:0 auto;padding:8px 20px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;}\r\n.mt-topbar-left{display:flex;gap:20px;flex-wrap:wrap;}\r\n.mt-tb-item{display:inline-flex;align-items:center;gap:6px;}\r\n.mt-tb-item .dashicons{font-size:15px;color:var(--mt-gold);}\r\n.mt-topbar