ent.elementor-element-f78403d6{background-position:center 78% !important;}\r\n/* MT PREMIUM POLISH */\r\n.elementor-button{transition:transform .25s ease,box-shadow .25s ease !important;}\r\n.elementor-button:hover{transform:translateY(-3px);box-shadow:0 12px 24px rgba(0,0,0,.25);}\r\n.elementor-icon-box-wrapper{transition:transform .25s ease;}\r\n.elementor-icon-box-wrapper:hover{transform:translateY(-4px);}\r\n.mt-gallery img,.elementor-widget-image img{transition:transform .4s ease;}\r\n.mt-gallery a:hover img,.elementor-widget-image:hover img{transform:scale(1.04);}\r\n.elementor-accordion-item{border:1px solid var(--mt-line);border-radius:8px;margin-bottom:10px;overflow:hidden;}\r\n.elementor-accordion-item .elementor-tab-title{background:var(--mt-bg);font-weight:700;}\r\n@media (prefers-reduced-motion: reduce){.elementor-button,.elementor-icon-box-wrapper,.mt-gallery img{transition:none !important;transform:none !important;}}\r\n/* MT UX PREMIUM */\r\n.mt-eyebrow{display:inline-block;font-family:Barlow,sans-serif;font-weight:800;font-size:12px;letter-spacing:3px;color:var(--mt-red);background:rgba(216,19,36,.08);border:1px solid rgba(216,19,36,.25);padding:6px 18px 6px 15px;border-radius:100px;}\r\n.mt-eyebrow::before{content:\"\";display:inline-block;width:22px;height:2px;background:var(--mt-gold);vertical-align:middle;margin-right:10px;}\r\n.mt-contact-rows span{display:block;padding:10px 0;border-bottom:1px solid rgba(255,255,255,.14);}\r\n.mt-contact-rows span:last-child{border-bottom:none;}\r\n.mt-contact-rows i{color:var(--mt-gold);width:26px;text-align:center;margin-right:8px;}\r\n.mt-steps div{display:flex;gap:14px;align-items:flex-start;padding:12px 0;border-bottom:1px dashed var(--mt-line);}\r\n.mt-steps div:last-child{border-bottom:none;}\r\n.mt-steps b{flex:0 0 34px;height:34px;border-radius:50%;background:var(--mt-navy);color:#fff;font-family:Barlow,sans-serif;display:flex;align-items:center;justify-content:center;font-size:16px;}\r\n.mt-card-shadow{box-shadow:0 18px 44px rgba(11,33,84,.12) !important;}\r\n.mt-soc a{display:inline-flex;width:38px;height:38px;border-radius:50%;border:1px solid rgba(255,255,255,.3);color:#fff !important;align-items:center;justify-content:center;margin-right:10px;font-size:16px;text-decoration:none;}\r\n.mt-soc a:hover{background:var(--mt-red);border-color:var(--mt-red);}\r\n.mt-flinks a{color:var(--mt-slate);text-decoration:none;line-height:2;}\r\n.mt-flinks a:hover{color:var(--mt-gold);}\r\n.elementor-accordion-item{border:1px solid var(--mt-line) !important;border-radius:10px !important;margin-bottom:12px !important;overflow:hidden;box-shadow:0 4px 14px rgba(11,33,84,.05);}\r\n.elementor-accordion-item .elementor-tab-title{background:var(--mt-bg) !important;}\r\n.elementor-accordion-item .elementor-tab-title.elementor-active{background:var(--mt-navy) !important;}\r\n.elementor-accordion-item .elementor-tab-title.elementor-active a{color:#fff !important;}\r\n/* MT FINAL SINGLE-FOOTER + BRANDS */\r\n.site-below-footer-wrap{display:none !important;}\r\n.mt-flinks a{text-decoration:none !important;}\r\n.mt-flinks a:hover{color:var(--mt-gold) !important;}\r\n.mt-copy{margin:0;}\r\n.mt-copy a{color:var(--mt-cream);text-decoration:none;}\r\n.mt-copy a:hover{color:#fff;}\r\n.mt-brands-label{border-top:4px solid var(--mt-red);}\r\n.mt-brands-label .elementor-container{min-height:0;}\r\n.mt-brands-strip .elementor-top-column + .elementor-top-column{border-left:1px solid rgba(245,158,11,.35);}\r\n@media(max-width:767px){.mt-brands-strip .elementor-top-column + .elementor-top-column{border-left:none;border-top:1px solid rgba(245,158,11,.25);padding-top:14px;}}\r\n/* MT PALETTE UNIFY */\r\n\r\n#ast-scroll-top{background-color:var(--mt-red) !important;}\r\n.ast-builder-menu-1 .sub-menu{border-color:var(--mt-red) !important;}\r\na:focus,.menu-link:focus,.elementor-button:focus{outline-color:var(--mt-gold) !important;}\r\n.ast-theme-transparent-header .main-header-menu .menu-link:hover,.main-header-menu .menu-item.current-menu-item > .menu-link{color:var(--mt-gold) !important;}\r\ninput:focus,textarea:focus,select:focus{border-color:var(--mt-navy) !important;box-shadow:0 0 0 1px var(--mt-navy) !important;}\r\n::selection{background:var(--mt-red);color:#fff;}\r\n.elementor-widget-testimonial .elementor-testimonial__image img{border:2px solid var(--mt-gold);}\r\n.mt-flinks a:hover,.mt-copy a:hover{color:var(--mt-gold) !important;}\r\n/* MT BRAND CARDS */\r\n.mt-brand{text-align:center;padding:22px 10px;border:1px solid rgba(245,158,11,.28);border-radius:14px;background:rgba(255,255,255,.03);transition:transform .25s ease,box-shadow .25s ease,border-color .25s ease;height:100%;}\r\n.mt-brand:hover{transform:translateY(-5px);border-color:var(--mt-gold);box-shadow:0 14px 30px rgba(0,0,0,.35),0 0 0 1px var(--mt-gold);}\r\n.mt-brand-badge{display:inline-flex;width:68px;height:68px;border-radius:50%;border:2px solid var(--mt-gold);color:var(--mt-cream);font-family:Barlow,sans-serif;font-weight:800;font-size:24px;align-items:center;justify-content:center;margin-bottom:12px;background:rgba(245,158,11,.08);}\r\n.mt-brand strong{display:block;color:#fff;font-family:Barlow,sans-serif;font-weight:800;font-size:17px;letter-spacing:1px;margin-bottom:4px;}\r\n.mt-brand small{display:block;color:var(--mt-slate);font-size:12px;}\r\n.mt-brands-strip .elementor-top-column + .elementor-top-column{border:none !important;}\r\n/* MT BRAND ONE + KONTAK GAP */\r\n.mt-brands{border-top:4px solid var(--mt-red);}\r\n.mt-brand-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:18px;max-width:1220px;margin:22px auto 0;padding:0 20px;}\r\n@media(max-width:921px){.mt-brand-grid{grid-template-columns:repeat(3,1fr);}}\r\n@media(max-width:600px){.mt-brand-grid{grid-template-columns:repeat(2,1fr);gap:14px;}}\r\n.mt-kontak .elementor-top-column{margin-bottom:0;}\r\n@media(max-width:767px){.mt-kontak .elementor-top-column{margin-left:0 !important;margin-right:0 !important;margin-bottom:20px !important;}.mt-kontak .elementor-top-column:last-child{margin-bottom:0 !important;}}\r\n/* MT REVAMP: tombol sebaris */\r\n.mt-btn-row .elementor-widget-wrap > .elementor-element.elementor-widget-button{width:auto;}\r\n.mt-btn-row .elementor-widget-button + .elementor-widget-button{margin-left:14px;}\r\n@media(max-width:767px){\r\n.mt-btn-row .elementor-widget-wrap > .elementor-element.elementor-widget-button{width:100%;}\r\n.mt-btn-row .elementor-widget-button + .elementor-widget-button{margin-left:0;margin-top:12px;}\r\n}\r\n/* MT REVAMP: matikan underline bawaan Astra di konten */\r\n.entry-content a,.entry-content .elementor-accordion-title{text-decoration:none !important;}\r\n.entry-content a:hover,.entry-content .elementor-accordion-title:hover{text-decoration:underline !important;}\r\n/* MT REVAMP: avatar testimoni */\r\n.elementor-testimonial-image img{border-radius:50%;}\r\n/* MT REVAMP: kartu brand terang (logo asli) di atas navy */\r\n.mt-brand-grid{margin:4px auto 0;}\r\n.mt-brand{background:#FFFFFF;border:1px solid var(--mt-line);padding:20px 12px 18px;border-radius:14px;box-shadow:0 8px 22px rgba(0,0,0,.18);}\r\n.mt-brand:hover{background:#FFFFFF;transform:translateY(-6px);border-color:var(--mt-gold);box-shadow:0 16px 34px rgba(0,0,0,.32),0 0 0 1px var(--mt-gold);}\r\n.mt-brand-logo{display:flex;align-items:center;justify-content:center;height:54px;margin-bottom:12px;}\r\n.mt-brand-logo img{max-height:44px;max-width:80%;width:auto;height:auto;object-fit:contain;display:block;}\r\n.mt-brand strong{color:var(--mt-navy);font-size:15px;letter-spacing:1.2px;}\r\n.mt-brand small{color:var(--mt-muted);font-size:12px;}\r\n.mt-wm{position:relative;display:inline-block;font-family:Barlow,sans-serif;font-weight:800;font-size:27px;letter-spacing:2px;color:var(--mt-navy);padding-bottom:9px;line-height:1;}\r\n.mt-wm::after{content:\"\";position:absolute;left:50%;transform:translateX(-50%);bottom:0;width:78%;height:3px;border-radius:2px;background:linear-gradient(90deg,var(--mt-red),var(--mt-gold));}\r\n.mt-wm-split i{font-style:normal;color:var(--mt-red);}\r\n.mt-wm-split{color:var(--mt-navy);}\r\n/* MT REVAMP 2b: centering tombol hero + CTA */\r\n.mt-btn-row-c .elementor-widget-wrap{justify-content:center;}\r\n/* MT REVAMP 2b: nama testimoni &amp; judul FAQ ke palet navy */\r\n.elementor-testimonial-name{color:var(--mt-navy) !important;font-weight:800;}\r\n.elementor-testimonial-job{color:var(--mt-muted) !important;}\r\n.elementor-accordion-title{color:var(--mt-navy) !important;font-weight:700;}\r\n.elementor-accordion-item.elementor-active .elementor-accordion-title{color:#FFFFFF !important;}\r\n.elementor-accordion-icon{color:var(--mt-red) !important;}\r\n.elementor-accordion-item.elementor-active .elementor-accordion-icon{color:var(--mt-gold) !important;}\r\n/* MT REVAMP 2c: center tombol hero/CTA di mobile */\r\n@media(max-width:767px){.mt-btn-row-c .elementor-widget-button{text-align:center;}}\r\n\r\n/* MT REVAMP 2d: ikon accordion + hamburger ke palet brand, alignment tombol row */\r\n.elementor-widget-accordion .elementor-accordion-icon svg{fill:var(--mt-red) !important;}\r\n.elementor-widget-accordion .elementor-active .elementor-accordion-icon svg{fill:var(--mt-gold) !important;}\r\n.mobile-menu-toggle-icon svg{fill:var(--mt-navy) !important;}\r\n.mt-btn-row .elementor-widget-button{margin-bottom:0 !important;}\r\n\r\n/* MT REVAMP 2e: anchor galeri (tanpa teks) ikut palet */\r\n.elementor-element-25d50a30 a{color:var(--mt-navy);}\r\n\r\n@media(max-width:767px){.mt-btn-row .elementor-button{width:100%;display:block;text-align:center;}}\r\n\r\n\r\n/* MT FASE 3: sub-halaman premium */\r\n.page-id-31 .entry-header,.page-id-32 .entry-header,.page-id-33 .entry-header,.page-id-34 .entry-header,\r\n.single-post.postid-24 .entry-header,.single-post.postid-25 .entry-header,.single-post.postid-26 .entry-header,\r\n.single-post.postid-27 .entry-header,.single-post.postid-28 .entry-header,.single-post.postid-29 .entry-header{display:none!important;}\r\n.mt-pg-hero{position:relative;overflow:hidden;background-image:linear-gradient(135deg,var(--mt-navy) 0%,var(--mt-dark) 100%)!important;}\r\n.mt-pg-hero::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:4px;background:linear-gradient(90deg,var(--mt-red),var(--mt-gold));z-index:3;}\r\n.mt-pg-hero .elementor-container{position:relative;z-index:2;}\r\n.mt-eyebrow-light{color:var(--mt-cream);background:rgba(245,158,11,.1);border-color:rgba(245,158,11,.35);}\r\n.mt-crumb{font-size:13.5px;letter-spacing:.3px;}\r\n.mt-crumb a{color:var(--mt-cream);text-decoration:none;}\r\n.mt-crumb a:hover{color:#FFFFFF;text-decoration:none;}\r\n.mt-crumb i{font-style:normal;color:rgba(255,255,255,.35);margin:0 8px;}\r\n.mt-crumb b{color:var(--mt-slate);font-weight:600;}\r\n.mt-lead{margin-top:14px;max-width:880px;}\r\n.mt-pg-hero .mt-lead{color:var(--mt-slate);}\r\n.mt-lead-dark{margin-top:14px;color:var(--mt-text);}\r\n.mt-checks{list-style:none;margin:22px 0 0;padding:0;}\r\n.mt-checks li{position:relative;padding-left:34px;margin-bottom:12px;color:#334155;font-size:15.5px;line-height:1.65;}\r\n.mt-checks li::before{content:\"✓\";position:absolute;left:0;top:1px;width:22px;height:22px;border-radius:50%;background:var(--mt-navy);color:var(--mt-gold);font-size:12px;line-height:22px;text-align:center;font-weight:700;}\r\n.mt-cards{display:grid;gap:18px;grid-template-columns:repeat(4,1fr);margin-top:28px;text-align:left;}\r\n.mt-cards.c3{grid-template-columns:repeat(3,1fr);}\r\n.mt-cards.c2{grid-template-columns:repeat(2,1fr);}\r\n.mt-card{background:#FFFFFF;border:1px solid var(--mt-line);border-top:3px solid var(--mt-navy);border-radius:14px;padding:24px 22px;box-shadow:0 10px 26px rgba(11,33,84,.07);transition:transform .25s ease,box-shadow .25s ease,border-color .25s ease;height:100%;}\r\n.mt-card:hover{transform:translateY(-5px);border-top-color:var(--mt-red);box-shadow:0 18px 38px rgba(11,33,84,.14);}\r\n.mt-card .ic{display:inline-flex;width:46px;height:46px;border-radius:12px;background:rgba(216,19,36,.08);color:var(--mt-red);align-items:center;justify-content:center;font-size:19px;}\r\n.mt-card h4{font-family:Barlow,sans-serif;font-weight:800;color:var(--mt-navy);font-size:17.5px;margin:16px 0 8px;}\r\n.mt-card p{margin:0;color:var(--mt-muted);font-size:14.5px;line-height:1.7;}\r\n.mt-card ul{list-style:none;margin:14px 0 0;padding:0;}\r\n.mt-card ul li{position:relative;padding-left:20px;color:var(--mt-text);font-size:14.5px;line-height:1.65;margin-bottom:7px;}\r\n.mt-card ul li::before{content:\"\";position:absolute;left:2px;top:9px;width:7px;height:7px;border-radius:50%;background:var(--mt-gold);}\r\n.mt-chips{display:flex;flex-wrap:wrap;gap:10px;margin-top:24px;}\r\n.mt-chips span{background:#FFFFFF;border:1px solid var(--mt-line);border-left:3px solid var(--mt-red);border-radius:100px;padding:9px 20px;font-family:Barlow,sans-serif;font-weight:700;color:var(--mt-navy);font-size:14.5px;box-shadow:0 4px 12px rgba(11,33,84,.05);}\r\n.mt-note{background:#FFF8E7;border:1px solid rgba(245,158,11,.4);border-left:4px solid var(--mt-gold);border-radius:10px;padding:16px 20px;color:#78350F;font-size:15px;line-height:1.7;margin-top:26px;}\r\n.mt-links{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:26px;text-align:left;}\r\n.mt-links a{display:block;background:#FFFFFF;border:1px solid var(--mt-line);border-radius:12px;padding:18px 44px 18px 20px;text-decoration:none;transition:transform .25s ease,box-shadow .25s ease,border-color .25s ease;position:relative;}\r\n.mt-links a b{display:block;font-family:Barlow,sans-serif;font-weight:700;color:var(--mt-navy);font-size:16px;margin-bottom:4px;}\r\n.mt-links a span{display:block;color:var(--mt-muted);font-size:13.5px;line-height:1.55;}\r\n.mt-links a::after{content:\"→\";position:absolute;right:18px;top:16px;color:var(--mt-red);font-weight:700;}\r\n.mt-links a:hover{border-color:var(--mt-gold);box-shadow:0 12px 26px rgba(11,33,84,.12);transform:translateY(-3px);}\r\n.mt-links a.is-current{border-left:4px solid var(--mt-red);background:var(--mt-bg);}\r\n.mt-mini-rows{margin-top:18px;}\r\n.mt-mini-rows span{display:block;padding:12px 0;border-bottom:1px solid rgba(255,255,255,.14);}\r\n.mt-mini-rows span:last-child{border-bottom:none;padding-bottom:0;}\r\n.mt-mini-rows i{color:var(--mt-gold);width:24px;text-align:center;margin-right:8px;}\r\n.mt-mini-rows b{display:block;color:var(--mt-cream);font-family:Barlow,sans-serif;font-size:11.5px;letter-spacing:1.6px;text-transform:uppercase;margin-bottom:5px;}\r\n.mt-btn-inline{display:flex;gap:12px;flex-wrap:wrap;margin-top:8px;}\r\n.mt-btn{display:inline-block;background:var(--mt-green);color:#FFFFFF!important;font-family:Barlow,sans-serif;font-weight:700;font-size:15px;padding:13px 26px;border-radius:8px;text-decoration:none;transition:transform .25s ease,box-shadow .25s ease;}\r\n.mt-btn-red{background:var(--mt-red);}\r\n.mt-btn:hover{transform:translateY(-3px);box-shadow:0 12px 24px rgba(0,0,0,.25);color:#FFFFFF!important;text-decoration:none;}\r\n@media(max-width:921px){.mt-cards,.mt-cards.c3{grid-template-columns:repeat(2,1fr);}.mt-links{grid-template-columns:repeat(2,1fr);}}\r\n@media(max-width:600px){.mt-cards,.mt-cards.c3,.mt-cards.c2{grid-template-columns:1fr;}.mt-links{grid-template-columns:1fr;}.mt-btn-inline{flex-direction:column;}.mt-btn{width:100%;text-align:center;}}\r\n\r\n/* MT FASE 3b: ritme spacing + chips + kartu est */\r\n.mt-lead,.mt-lead-dark{margin-bottom:0;}\r\n.mt-checks{margin-top:6px;}\r\n.mt-mini-rows{margin-top:0;}\r\n.mt-est{align-self:flex-start;}\r\n.mt-chips span{position:relative;padding-left:34px;border-left:0;}\r\n.mt-chips span::before{content:\"\";position:absolute;left:16px;top:50%;width:7px;height:7px;border-radius:50%;background:var(--mt-red);transform:translateY(-50%);}\r\n\r\n/* MT FASE 3c: gutter tablet/mobile */\r\n@media(max-width:1024px){\r\n.page-id-31 .elementor-column-gap-default .elementor-widget-wrap,.page-id-32 .elementor-column-gap-default .elementor-widget-wrap,.page-id-33 .elementor-column-gap-default .elementor-widget-wrap,.page-id-34 .elementor-column-gap-default .elementor-widget-wrap,.single-post.postid-24 .elementor-column-gap-default .elementor-widget-wrap,.single-post.postid-25 .elementor-column-gap-default .elementor-widget-wrap,.single-post.postid-26 .elementor-column-gap-default .elementor-widget-wrap,.single-post.postid-27 .elementor-column-gap-default .elementor-widget-wrap,.single-post.postid-28 .elementor-column-gap-default .elementor-widget-wrap,.single-post.postid-29 .elementor-column-gap-default .elementor-widget-wrap{padding-left:20px!important;padding-right:20px!important;}\r\n}\r\n@media(max-width:600px){\r\n.page-id-31 .mt-brand-grid,.page-id-32 .mt-brand-grid,.page-id-33 .mt-brand-grid,.page-id-34 .mt-brand-grid,.single-post.postid-24 .mt-brand-grid,.single-post.postid-25 .mt-brand-grid,.single-post.postid-26 .mt-brand-grid,.single-post.postid-27 .mt-brand-grid,.single-post.postid-28 .mt-brand-grid,.single-post.postid-29 .mt-brand-grid{padding-left:0!important;padding-right:0!important;}\r\n}\r\n/* MT FASE 3d: sembunyikan komentar &amp; prev-next bawaan */\r\n.single-post.postid-24 .comments-area,.single-post.postid-24 .post-navigation,.single-post.postid-25 .comments-area,.single-post.postid-25 .post-navigation,.single-post.postid-26 .comments-area,.single-post.postid-26 .post-navigation,.single-post.postid-27 .comments-area,.single-post.postid-27 .post-navigation,.single-post.postid-28 .comments-area,.single-post.postid-28 .post-navigation,.single-post.postid-29 .comments-area,.single-post.postid-29 .post-navigation{display:none;}\r\n/* MT FASE 3e: hilangkan margin bawah entry-content (strip putih di bawah footer) */\r\n.page-id-31 .entry-content,.page-id-32 .entry-content,.page-id-33 .entry-content,.page-id-34 .entry-content,.single-post.postid-24 .entry-content,.single-post.postid-25 .entry-content,.single-post.postid-26 .entry-content,.single-post.postid-27 .entry-content,.single-post.postid-28 .entry-content,.single-post.postid-29 .entry-content{margin-bottom:0!important;}\r\n\r\n/* ================= MT FASE 4: modern industrial refresh ================= */\r\n\r\n/* --- satu keluarga font untuk seluruh situs --- */\r\nbody,button,input,select,textarea,.mt-topbar{font-family:\"Barlow\",-apple-system,BlinkMacSystemFont,\"Segoe UI\",Roboto,Oxygen-Sans,Ubuntu,Cantarell,\"Helvetica Neue\",sans-serif;}\r\n\r\n/* --- tombol pill + micro-interaction --- */\r\n.elementor-button{border-radius:var(--mt-r-pill)!important;padding-left:26px!important;padding-right:26px!important;}\r\n.main-header-menu .fleet-btn > .menu-link{border-radius:var(--mt-r-pill)!important;}\r\n.mt-tb-reg{border-radius:var(--mt-r-pill)!important;}\r\n.mt-btn{border-radius:var(--mt-r-pill);}\r\n\r\n/* --- radius &amp; shadow seragam --- */\r\n.mt-card,.mt-brand{border-radius:var(--mt-r-md);}\r\n.mt-card{box-shadow:var(--mt-sh-1);}\r\n.mt-card:hover{box-shadow:var(--mt-sh-2);}\r\n.mt-links a{border-radius:var(--mt-r-sm);}\r\n.elementor-accordion-item{border-radius:var(--mt-r-sm)!important;box-shadow:var(--mt-sh-1);}\r\n.mt-chips span{border-radius:var(--mt-r-pill)!important;}\r\n\r\n/* --- highlight frasa ala headline modern --- */\r\n\r\n/* --- kartu statistik melayang di bawah hero --- */\r\n.mt-stats{background:#fff!important;border:1px solid var(--mt-line);border-radius:var(--mt-r-md)!important;box-shadow:var(--mt-sh-3);max-width:1180px;margin:-72px auto 0!important;padding:30px 12px!important;position:relative;z-index:6;}\r\n.mt-stats > .elementor-container{max-width:100%!important;}\r\n.mt-stats .elementor-counter-number{color:var(--mt-navy)!important;font-weight:800;letter-spacing:-.5px;}\r\n.mt-stats .elementor-counter-number-prefix,.mt-stats .elementor-counter-number-suffix{color:var(--mt-red)!important;font-weight:800;}\r\n.mt-stats .elementor-counter-title{color:var(--mt-muted)!important;font-weight:600;letter-spacing:.3px;}\r\n@media(min-width:768px){.mt-stats .elementor-top-column + .elementor-top-column{border-left:1px solid var(--mt-line)!important;}}\r\n@media(max-width:767px){\r\n  .mt-stats{margin:0 16px!important;padding:22px 4px!important;}\r\n  .mt-stats .elementor-row{display:grid;grid-template-columns:repeat(2,1fr);}\r\n  .mt-stats .elementor-top-column{width:100%!important;padding:12px 8px!important;}\r\n  .mt-stats .elementor-top-column:nth-child(2n){border-left:1px solid var(--mt-line)!important;}\r\n  .mt-stats .elementor-top-column:nth-child(-n+2){border-bottom:1px solid var(--mt-line);}\r\n  .mt-stats .elementor-counter-number{font-size:34px!important;}\r\n}\r\n\r\n/* --- hero: jaga keterbacaan teks di atas foto --- */\r\n\r\n/* --- polish mobile --- */\r\n@media(max-width:600px){\r\n  .mt-topbar{font-size:11.5px;}\r\n  .mt-topbar-inner{padding:6px 14px;gap:8px;}\r\n  .mt-topbar-left{gap:12px;}\r\n  .mt-topbar-right a{font-size:11.5px;}\r\n  .mt-tb-reg{padding:3px 10px;}\r\n  .elementor-button{min-height:46px;}\r\n}\r\n@media(max-width:480px){\r\n  .mt-topbar-right a{font-weight:600;}\r\n  .mt-topbar-left{gap:10px;}\r\n}\r\n\r\n\r\n/* ==========================================================================\r\n   MT FOOTER MOBILE-FRIENDLY & RESPONSIVE POLISH (FASE 5)\r\n   ========================================================================== */\r\n\r\n/* Section wrapper & container bounds */\r\n.elementor-element.elementor-element-31e74b99,\r\n.mt-footer-main {\r\n  background-color: var(--mt-dark, #001E3D) !important;\r\n  color: var(--mt-slate, #CBD5E1) !important;\r\n  box-sizing: border-box !important;\r\n  border-top: 3px solid var(--mt-red, #D81324) !important;\r\n}\r\n\r\n.elementor-element.elementor-element-31e74b99 > .elementor-container,\r\n.mt-footer-main > .elementor-container {\r\n  max-width: 1220px !important;\r\n  margin: 0 auto !important;\r\n  padding: 0 20px !important;\r\n  box-sizing: border-box !important;\r\n  display: flex !important;\r\n  flex-wrap: wrap !important;\r\n}\r\n\r\n/* Headings (\"Layanan\", \"Perusahaan\", \"Hubungi Kami\") */\r\n.elementor-element.elementor-element-31e74b99 .elementor-heading-title {\r\n  color: var(--mt-gold, #F59E0B) !important;\r\n  font-family: \"Barlow\", sans-serif !important;\r\n  font-size: 16px !important;\r\n  font-weight: 700 !important;\r\n  letter-spacing: 0.6px !important;\r\n  text-transform: uppercase !important;\r\n  margin: 0 0 16px 0 !important;\r\n  padding-bottom: 6px !important;\r\n  border-bottom: 2px solid rgba(245, 158, 11, 0.4) !important;\r\n  display: inline-block !important;\r\n}\r\n\r\n/* Links Layanan & Perusahaan */\r\n.elementor-element.elementor-element-31e74b99 .mt-flinks {\r\n  margin: 0 !important;\r\n  display: flex !important;\r\n  flex-direction: column !important;\r\n}\r\n.elementor-element.elementor-element-31e74b99 .mt-flinks br {\r\n  display: none !important;\r\n}\r\n.elementor-element.elementor-element-31e74b99 .mt-flinks a {\r\n  display: inline-flex !important;\r\n  align-items: center !important;\r\n  padding: 6px 0 !important;\r\n  color: var(--mt-slate, #CBD5E1) !important;\r\n  font-size: 14px !important;\r\n  line-height: 1.5 !important;\r\n  text-decoration: none !important;\r\n  transition: all 0.2s ease !important;\r\n}\r\n.elementor-element.elementor-element-31e74b99 .mt-flinks a:hover {\r\n  color: var(--mt-gold, #F59E0B) !important;\r\n  transform: translateX(4px);\r\n}\r\n\r\n/* Kolom Kontak & Hubungi Kami */\r\n.mt-footer-contact {\r\n  display: flex;\r\n  flex-direction: column;\r\n  gap: 12px;\r\n  margin-top: 2px;\r\n}\r\n.mt-fc-item {\r\n  display: flex;\r\n  align-items: flex-start;\r\n  gap: 12px;\r\n  font-size: 14px;\r\n  line-height: 1.55;\r\n  color: var(--mt-slate, #CBD5E1);\r\n}\r\n.mt-fc-item i {\r\n  color: var(--mt-gold, #F59E0B);\r\n  font-size: 15px;\r\n  width: 18px;\r\n  text-align: center;\r\n  margin-top: 3px;\r\n  flex-shrink: 0;\r\n}\r\n.mt-fc-item a {\r\n  color: #FFFFFF !important;\r\n  text-decoration: none !important;\r\n  font-weight: 600;\r\n  transition: color 0.2s ease;\r\n}\r\n.mt-fc-item a:hover {\r\n  color: var(--mt-gold, #F59E0B) !important;\r\n  text-decoration: underline !important;\r\n}\r\n\r\n/* Social icons */\r\n.elementor-element.elementor-element-31e74b99 .mt-soc {\r\n  display: flex !important;\r\n  gap: 10px !important;\r\n  margin-top: 16px !important;\r\n  margin-bottom: 0 !important;\r\n}\r\n.elementor-element.elementor-element-31e74b99 .mt-soc a {\r\n  display: inline-flex !important;\r\n  width: 40px !important;\r\n  height: 40px !important;\r\n  border-radius: 50% !important;\r\n  border: 1px solid rgba(255, 255, 255, 0.2) !important;\r\n  background: rgba(255, 255, 255, 0.05) !important;\r\n  color: #FFFFFF !important;\r\n  align-items: center !important;\r\n  justify-content: center !important;\r\n  font-size: 15px !important;\r\n  text-decoration: none !important;\r\n  transition: all 0.25s ease !important;\r\n}\r\n.elementor-element.elementor-element-31e74b99 .mt-soc a:hover {\r\n  background: var(--mt-red, #D81324) !important;\r\n  border-color: var(--mt-red, #D81324) !important;\r\n  color: #FFFFFF !important;\r\n  transform: translateY(-2px);\r\n}\r\n\r\n/* DESKTOP (min-width: 1025px): 4 kolom simetris */\r\n@media (min-width: 1025px) {\r\n  .elementor-element.elementor-element-31e74b99 {\r\n    padding: 60px 0 44px 0 !important;\r\n  }\r\n  .elementor-element.elementor-element-31e74b99 .elementor-column.elementor-col-25 {\r\n    width: 25% !important;\r\n    flex: 0 0 25% !important;\r\n    max-width: 25% !important;\r\n    padding: 0 16px !important;\r\n    box-sizing: border-box !important;\r\n  }\r\n}\r\n\r\n/* TABLET (768px - 1024px): 2 kolom x 2 baris */\r\n@media (min-width: 768px) and (max-width: 1024px) {\r\n  .elementor-element.elementor-element-31e74b99 {\r\n    padding: 44px 0 32px 0 !important;\r\n  }\r\n  .elementor-element.elementor-element-31e74b99 > .elementor-container {\r\n    row-gap: 34px !important;\r\n  }\r\n  .elementor-element.elementor-element-31e74b99 .elementor-column.elementor-col-25 {\r\n    width: 50% !important;\r\n    flex: 0 0 50% !important;\r\n    max-width: 50% !important;\r\n    padding: 0 20px !important;\r\n    box-sizing: border-box !important;\r\n  }\r\n  .elementor-element.elementor-element-31e74b99 .elementor-widget-image img {\r\n    max-width: 200px !important;\r\n  }\r\n}\r\n\r\n/* MOBILE (<= 767px): 1 kolom tumpuk penuh, touch-friendly, rapi */\r\n@media (max-width: 767px) {\r\n  .elementor-element.elementor-element-31e74b99 {\r\n    padding: 36px 18px 24px 18px !important;\r\n  }\r\n  .elementor-element.elementor-element-31e74b99 > .elementor-container {\r\n    flex-direction: column !important;\r\n    gap: 26px !important;\r\n    padding: 0 !important;\r\n    width: 100% !important;\r\n  }\r\n  .elementor-element.elementor-element-31e74b99 .elementor-column.elementor-col-25 {\r\n    width: 100% !important;\r\n    flex: 0 0 100% !important;\r\n    max-width: 100% !important;\r\n    padding: 0 !important;\r\n    margin: 0 !important;\r\n    box-sizing: border-box !important;\r\n  }\r\n  /* Garis pemisah halus antar bagian di layar HP */\r\n  .elementor-element.elementor-element-31e74b99 .elementor-column.elementor-col-25:not(:last-child) {\r\n    border-bottom: 1px solid rgba(255, 255, 255, 0.08) !important;\r\n    padding-bottom: 22px !important;\r\n  }\r\n  /* Logo */\r\n  .elementor-element.elementor-element-31e74b99 .elementor-widget-image img {\r\n    max-width: 190px !important;\r\n    width: auto !important;\r\n    height: auto !important;\r\n  }\r\n  /* Deskripsi ringkas */\r\n  .elementor-element.elementor-element-5a9d8f4b p {\r\n    font-size: 13.5px !important;\r\n    line-height: 1.6 !important;\r\n    margin-bottom: 12px !important;\r\n  }\r\n  /* Link navigasi mobile: tombol baris sentuh yang nyaman */\r\n  .elementor-element.elementor-element-31e74b99 .mt-flinks a {\r\n    display: flex !important;\r\n    justify-content: space-between !important;\r\n    align-items: center !important;\r\n    padding: 10px 4px !important;\r\n    font-size: 14.5px !important;\r\n    border-bottom: 1px dashed rgba(255, 255, 255, 0.07) !important;\r\n    min-height: 44px !important;\r\n    box-sizing: border-box !important;\r\n  }\r\n  .elementor-element.elementor-element-31e74b99 .mt-flinks a:last-child {\r\n    border-bottom: none !important;\r\n  }\r\n  .elementor-element.elementor-element-31e74b99 .mt-flinks a::after {\r\n    content: \"›\";\r\n    color: var(--mt-gold, #F59E0B);\r\n    font-size: 18px;\r\n    font-weight: 700;\r\n  }\r\n  /* Kontak item di mobile */\r\n  .mt-fc-item {\r\n    padding: 8px 0;\r\n    border-bottom: 1px dashed rgba(255, 255, 255, 0.07);\r\n    min-height: 44px;\r\n    box-sizing: border-box;\r\n  }\r\n  .mt-fc-item:last-child {\r\n    border-bottom: none;\r\n  }\r\n  .mt-fc-item a {\r\n    display: inline-block;\r\n    padding: 2px 0;\r\n  }\r\n  /* Baris hak cipta di mobile */\r\n  .elementor-element.elementor-element-9ac64f9f {\r\n    padding: 16px 14px !important;\r\n  }\r\n  .elementor-element.elementor-element-9ac64f9f .mt-copy {\r\n    font-size: 11.5px !important;\r\n    line-height: 1.7 !important;\r\n  }\r\n}','astra','','inherit','closed','closed','','14-revision-v1','','','2026-10-05 08:01:05','2026-10-05 08:01:05','',14,'http://localhost:8080/?p=107',0,'revision','',0);
